        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (y+dy, x+dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == 5 and q not in seen:
                        seen.add(q); stack.append(q)
            min_r = min(y for y,x in component); max_r = max(y for y,x in component)
            min_c = min(x for y,x in component); max_c = max(x for y,x in component)
