def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    q = (y + dy, x + dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == 5 and q not in seen:
                        seen.add(q)
                        stack.append(q)
            min_r = min(y for y, x in comp)
            max_r = max(y for y, x in comp)
            min_c = min(x for y, x in comp)
            max_c = max(x for y, x in comp)
            # Fill the enclosed zero region and the missing cell in the top bar.
            for y in range(min_r + 1, max_r):
                for x in range(min_c + 1, max_c):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            for x in range(min_c, max_c + 1):
                if grid[min_r][x] == 0:
                    out[min_r][x] = 2
            # The pattern's upper bar projects left on the row above it.
            if min_r > 0:
                for x in range(max_c):
                    out[min_r - 1][x] = 2
    return out
